<?php
$commentTotal=(int)query('SELECT COUNT(*) FROM comments WHERE post_id=?',[$postId])->fetchColumn();$commentPages=max(1,(int)ceil($commentTotal/20));$commentPage=min($commentPages,max(1,(int)($_GET['comments_page']??1)));$commentOffset=($commentPage-1)*20;
$comments=query("SELECT c.*,u.display_name,r.display_name AS reply_name FROM comments c JOIN users u ON u.id=c.user_id LEFT JOIN comments p ON p.id=c.parent_id LEFT JOIN users r ON r.id=p.user_id WHERE c.post_id=? ORDER BY c.id DESC LIMIT 20 OFFSET $commentOffset",[$postId])->fetchAll();
?>
<section class="panel comments-panel" id="comments" data-comments-post="<?=$postId?>"><h2><?=e(t('Comments'))?> <small class="muted"><?=$social['comments']?> <?=e(t('comments'))?></small></h2>
<?php if($reader):?><form id="comment-form"><input type="hidden" name="post_id" value="<?=$postId?>"><input type="hidden" name="parent_id" value=""><div class="comment-compose"><span class="avatar"><?=e(mb_strtoupper(mb_substr($reader['display_name'],0,1)))?></span><div class="comment-editor"><p data-reply-label hidden></p><label class="sr-only" for="comment-body"><?=e(t('Write a comment'))?></label><textarea id="comment-body" name="body" rows="4" maxlength="2000" required placeholder="<?=e(t('Share your thoughts…'))?>"></textarea><div class="comment-controls"><small class="muted"><?=e(t('Up to 2000 characters'))?></small><button type="button" class="text-button" data-cancel-reply hidden><?=e(t('Cancel reply'))?></button><button class="button" type="submit"><?=e(t('Post comment'))?></button></div><p role="status" aria-live="polite"></p></div></div></form>
<?php else:?><div class="comment-signin"><p><?=e(t('Sign in to join the discussion.'))?></p><a class="button secondary" href="/login?next=<?=rawurlencode('/?post='.$postId.'#comments')?>"><?=e(t('Sign in'))?></a><a class="text-button" href="/register"><?=e(t('Create account'))?></a></div><?php endif;?>
<div class="comment-list"><?php foreach($comments as $comment):?><article class="comment-item" id="comment-<?=$comment['id']?>"><span class="avatar"><?=e(mb_strtoupper(mb_substr($comment['display_name'],0,1)))?></span><div class="comment-main"><div class="comment-author"><strong><?=e($comment['display_name'])?></strong><?php if((int)$comment['user_id']===(int)$post['user_id']):?><span class="comment-author-badge"><?=e(t('Author'))?></span><?php endif;?><time class="muted"><?=e(substr($comment['created_at'],0,16))?></time></div><?php if($comment['reply_name']):?><p class="comment-reply-to muted"><?=e(t('Reply to'))?> @<?=e($comment['reply_name'])?></p><?php endif;?><div class="comment-text"><?= $comment['status']==='deleted'?e(t('This comment was deleted.')):nl2br(e($comment['body']))?></div><div class="comment-item-actions"><?php if($reader&&$comment['status']==='published'):?><button class="text-button" type="button" data-reply-id="<?=$comment['id']?>" data-reply-name="<?=e($comment['display_name'])?>"><?=e(t('Reply'))?></button><?php if((int)$reader['id']===(int)$comment['user_id']||isAdministrator()):?><button class="text-button" type="button" data-comment-delete="<?=$comment['id']?>"><?=e(t('Delete'))?></button><?php endif;endif;?></div></div></article><?php endforeach;?></div>
<?php if(!$commentTotal):?><p class="comment-empty muted"><?=e(t('Be the first to comment.'))?></p><?php endif;?>
<?php if($commentPages>1):?><nav class="pagination" aria-label="<?=e(t('Comments'))?>"><?php foreach([-1=>'Previous',1=>'Next'] as $step=>$label):if($commentPage+$step<1||$commentPage+$step>$commentPages)continue;?><a href="/?post=<?=$postId?>&amp;comments_page=<?=$commentPage+$step?>#comments"><?=e(t($label))?></a><?php endforeach;?><span><?=$commentPage?> / <?=$commentPages?></span></nav><?php endif;?></section>
